def smooth_path(knots,n):
 # Chord-length Catmull-Rom sampling of explicitly authored strokes; no scalp projection.
 d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(knots,axis=0),axis=1))];u=np.linspace(0,d[-1],n);i=np.minimum(np.searchsorted(d,u,side='right')-1,len(knots)-2);i=np.maximum(i,0);t=(u-d[i])/(d[i+1]-d[i]);p0=knots[np.maximum(i-1,0)];p1=knots[i];p2=knots[i+1];p3=knots[np.minimum(i+2,len(knots)-1)];t=t[:,None]
 return .5*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t*t*t)
