 owner=np.argmin(dist,axis=1);t=np.linspace(0,1,stations);G=guides[owner];rootOffset=roots-V[rootIds[owner]];P=G+rootOffset[:,None,:]*(1-t[None,:,None])**1.5
 tangent=np.gradient(G,axis=1);tangent/=np.maximum(np.linalg.norm(tangent,axis=2,keepdims=True),1e-8);side=np.cross(tangent,np.array([0.,0.,1.]));bad=np.linalg.norm(side,axis=2)<.05;side[bad]=np.cross(tangent,np.array([0.,1.,0.]))[bad];side/=np.maximum(np.linalg.norm(side,axis=2,keepdims=True),1e-8);other=np.cross(tangent,side)
